<body>

    <div id="desktop">
        <!-- Placeholder for desktop widgets/icons could go here -->
    </div>

    <div id="taskbar">
        <button class="launcher" id="open-files">Files</button>
        <button class="launcher" id="open-notepad">Notepad</button>
    </div>

    <!-- ============================= -->
    <!-- 1. FILES WINDOW -->
    <!-- ============================= -->
    <div id="files-window" class="app-window">
        <div class="window-title" id="files-title">
            <span>File Browser</span>
            <button class="win-close" data-target="files-window">&times;</button>
        </div>
