            <div id="files-controls">
                <button class="launcher" id="files-up">&uarr; Up</button>
                <div></div> <!-- Spacer -->
                <!-- Double click functionality handled by JS data attributes -->
            </div>

            <div id="file-listing">
                <!-- File listing populated by JavaScript -->
            </div>
        </div>
    </div>

    <!-- ============================= -->
