    <!-- ============================= -->
    <div id="notepad-window" class="app-window">
        <div class="window-title" id="notepad-title">
            <span>Notepad</span>
            <button class="win-close" data-target="notepad-window">&times;</button>
        </div>

        <div class="window-content">
            <!-- Tab Strip -->
