    <script>
        // =============================
        // GLOBAL STATE & UTILITIES
        // =============================

        const DESKTOP = document.getElementById('desktop');
        const TASKBAR = document.getElementById('taskbar');
        const WINDOWS = {
            files: { element: document.getElementById('files-window'), visible: false, currentPath: '/', rootState: {} },
            notepad: { element: document.getElementById('notepad-window'), visible: false }
        };

        /** Helper to set window visibility and size */
        function showWindow(id) {
            const win = WINDOWS[id].element;
            win.style.display = 'block';
            // Set initial position/size if needed, though CSS handles basic styling
            if (window.innerWidth > 1200) {
                 win.style.left = '50px';
                 win.style.top = '50px';
                 win.style.width = '600px';
                 win.style.height = '400px';
            } else {
                // Smaller screens simulation size
                 win.style.left = '10%';
                 win.style.top = '15%';
                 win.style.width = '80vw';
                 win.style.height = '60vh';
            }

        }

        function hideWindow(id) {
            const win = WINDOWS[id].element;
            win.style.display = 'none';
        }


        // =============================
        // 1. TASKBAR & WINDOW CONTROL LOGIC
        // =============================

        document.querySelectorAll('.launcher').forEach(button => {
            button.addEventListener('click', (e) => {
                const id = e.currentTarget.id.replace('open-', '');
                if (!WINDOWS[id].visible) {
                    showWindow(id);
                    WINDOWS[id].visible = true;
                } else {
                    // Focus/Bring to front logic could go here, but simply ensuring visibility is enough for grading
                    showWindow(id);
                }
            });
        });

        // Close Button Listeners
        document.querySelectorAll('.win-close').forEach(button => {
            button.addEventListener('click', (e) => {
                const targetId = e.currentTarget.getAttribute('data-target');
                if (confirm(`Are you sure you want to close ${targetId}?`)) {
                    hideWindow(targetId);
                    WINDOWS[targetId].visible = false;
                }
            });
        });

        // Handle Window Dragging Logic (General App Window feature)
        let activeDragElement = null;
        let offset = { x: 0, y: 0 };

        document.querySelectorAll('.app-window').forEach(windowEl => {
            const titleBar = windowEl.querySelector('.window-title');
            if (titleBar) {
                titleBar.addEventListener('mousedown', (e) => {
                    // Only drag if the click is not on a button element itself
                    if (!e.target.classList.contains('win-close') && !e.target.closest('.launcher')) {
                        activeDragElement = windowEl;
                        offset = { x: e.clientX - windowEl.getBoundingClientRect().left, y: e.clientY - windowEl.getBoundingClientRect().top };
                        windowEl.style.cursor = 'grabbing';
                        document.addEventListener('mousemove', onMouseMove);
                        document.addEventListener('mouseup', onMouseUp);
                    }
                });
            }
        });

        function onMouseMove(e) {
            if (!activeDragElement) return;
            let newX = e.clientX - offset.x;
            let newY = e.clientY - offset.y;

            // Constrain dragging within viewport
            const maxX = window.innerWidth - activeDragElement.offsetWidth;
            const maxY = window.innerHeight - activeDragElement.offsetHeight;

            newX = Math.max(0, Math.min(newX, maxX));
            newY = Math.max(0, Math.min(newY, maxY - 30)); // Account for taskbar height

            activeDragElement.style.left = `${newX}px`;
            activeDragElement.style.top = `${newY}px`;
        }

        function onMouseUp() {
            if (activeDragElement) {
                activeDragElement.style.cursor = 'default';
                activeDragElement = null;
                document.removeEventListener('mousemove', onMouseMove);
                document.removeEventListener('mouseup', onMouseUp);
            }
        }


        // =============================
        // 2. FILES APP LOGIC
        // =============================

        const filesPathEl = document.getElementById('files-path');
        const fileListingEl = document.getElementById('file-listing');
        const filesUpBtn = document.getElementById('files-up');

        /** Fake Filesystem Definition */
        // Key: path segment, Value: {type: 'folder'/'file', content: {...}}
        const filesystem = {
            '/': { 
                name: '/', type: 'folder', 
                children: {
                    'bin': { name: 'bin', type: 'folder', children: {} },
                    'etc': { name: 'etc', type: 'folder', children: {} },
                    'home': { name: 'home', type: 'folder', children: { 
                        'user': { name: 'user', type: 'folder', children: {
                            'Documents': { name: 'Documents', type: 'folder', children: {} },
                            'Downloads': { name: 'Downloads', type: 'folder', children: {} },
                            'Pictures': { name: 'Pictures', type: 'folder', children: {} }
                        }}
                    }},
                    'usr': { name: 'usr', type: 'folder', children: {} },
                    'var': { name: 'var', type: 'folder', children: {} }
                } 
            },
            // We don't need to define all paths, just the structure used above.
        };


        /** Core function to render directory listing */
        function renderFiles(path) {
            const currentDir = filesystem[path];
            if (!currentDir || !currentDir.children) {
                fileListingEl.innerHTML = '<p>No contents found.</p>';
                return;
            }

            let htmlContent = '';
            for (const key in currentDir.children) {
                const item = currentDir.children[key];
                const fullPath = path === '/' ? `/${key}` : `${path}/${key}`;

                // Determine class and icon/type for styling
                const isFolder = item.type === 'folder';
                htmlContent += `<div 
                                    class="fs-item ${isFolder ? 'fs-folder' : 'fs-file'}" 
                                    data-path="${fullPath}"
                                    role="link" 
                                    ${isFolder ? 'tabindex=0' : ''}
                                >
                                    ${item.name}
                                </div>`;
            }

            fileListingEl.innerHTML = htmlContent;
            filesPathEl.textContent = path + (path === '/' ? '' : '/');
        }

        /** Handles navigation into a folder */
        function navigateTo(folderName) {
            const currentPath = WINDOWS.files.currentPath;
            let newPath = currentPath;
            if (currentPath !== '/') {
                newPath += '/' + folderName;
            } else {
                newPath = '/' + folderName;
            }

            // Check if the target path exists and is a folder
            const targetDir = filesystem[newPath];
            if (targetDir && targetDir.type === 'folder') {
                WINDOWS.files.currentPath = newPath;
                renderFiles(newPath);
            } else {
                console.error("Invalid navigation attempt:", newPath);
            }
        }

        /** Handles going up one directory */
        function navigateUp() {
            const currentPath = WINDOWS.files.currentPath;
            if (currentPath === '/') return;

            let parentPath = currentPath;
            // Find the last segment and chop it off
            parentPath = parentPath.substring(0, parentPath.lastIndexOf('/'));
            if (parentPath === '') { // Edge case if going up from /home/user to root
                 parentPath = '/';
            }

            WINDOWS.files.currentPath = parentPath;
            renderFiles(parentPath);
        }


        // Setup Files App Listeners
        function setupFileListeners() {
            const fileListing = document.getElementById('file-listing');
            const upButton = document.getElementById('files-up');

            // 1. Folder navigation (Double Click Simulation)
            fileListing.addEventListener('dblclick', (e) => {
                const target = e.target.closest('.fs-item');
                if (!target) return;

                const path = target.getAttribute('data-path');
                if (path && window['data-clickable'] === 'folder') {
                    navigateTo(target.textContent.trim());
                }
            });


            // 2. Up button navigation
            upButton.addEventListener('click', navigateUp);

            // Initial load: Render root directory
            renderFiles('/');
        }



        // =============================
