        const TABS_STORAGE_KEY = 'desktopNotepadTabs';
        let activeTabIdCounter = 0; // Used for local unique IDs

        /** Initializes the Notepad state from localStorage or provides default tabs */
        function loadNotebookState() {
            const savedData = localStorage.getItem(TABS_STORAGE_KEY);
            if (savedData) {
                return JSON.parse(savedData);
            } else {
                 // Default startup state: one tab
                 return [{ id: 'welcome', title: 'Welcome Note', content: 'Start writing here! This content persists even if you close the page.' }];
            }
        }

        /** Renders tabs and sets up initial state based on loaded data */
        function renderTabs(tabsData) {
            const tabsContainer = document.getElementById('tabs');
            const editorEl = document.getElementById('editor');
            tabsContainer.innerHTML = ''; // Clear existing tabs
            let activeTabId = null;

            tabsData.forEach((tab, index) => {
                // 1. Create Tab Element
                const tabButton = document.createElement('button');
                tabButton.className = 'tab';
                tabButton.textContent = tab.title;
                tabButton.dataset.tabId = tab.id;
                tabButton.setAttribute('role', 'tab');

                // 2. Attach Event Listener
                tabButton.addEventListener('click', () => {
                    switchTab(tabButton);
                });
                tabsContainer.appendChild(tabButton);

                // 3. Initialize Content (Store content in a data attribute on the textarea for retrieval)
                if (index === 0 || tab.id === 'welcome') {
                     editorEl.value = tab.content;
                     activeTabId = tab.id;
                } else {
                     // If not active, ensure the editor is focused/updated when switching
                }
            });

            if (tabsData.length > 0) {
                 setActiveTab(activeTabId || tabsData[0].id);
            }
        }


        /** Switches the visible tab and updates the textarea content */
        function switchTab(clickedButton) {
            const container = document.getElementById('tabs');
            const editorEl = document.getElementById('editor');

            // Deactivate all tabs
            container.querySelectorAll('.tab').forEach(btn => btn.classList.remove('active'));
            // Activate clicked tab
            clickedButton.classList.add('active');

            // Update the textarea content (The text content is associated with the tab's data ID)
            const tabId = clickedButton.dataset.tabId;
            const currentTabsState = JSON.parse(localStorage.getItem(TABS_STORAGE_KEY));
            const activeTabData = currentTabsState.find(t => t.id === tabId);

            if (activeTabData) {
                editorEl.value = activeTabData.content;
                editorEl.focus(); // Focus on the editor when switching tabs
            } else {
                 // Fallback if data structure is corrupted
                 editorEl.value = "";
            }
        }

        /** Creates and switches to a new tab */
        function createNewTab() {
            const initialTitle = 'Untitled';
            const initialContent = '';
            activeTabIdCounter++;
            const newTabId = `tab-${Date.now()}-${activeTabIdCounter}`;

            // 1. Update Data State
            let currentTabsState = JSON.parse(localStorage.getItem(TABS_STORAGE_KEY) || '[]');
            currentTabsState.push({ id: newTabId, title: initialTitle, content: initialContent });
            localStorage.setItem(TABS_STORAGE_KEY, JSON.stringify(currentTabsState));

            // 2. Render the UI update
            const tabsContainer = document.getElementById('tabs');
            const newButton = document.createElement('button');
            newButton.className = 'tab active'; // Set immediately active
            newButton.textContent = initialTitle;
            newButton.dataset.tabId = newTabId;
            newButton.setAttribute('role', 'tab');
            newButton.addEventListener('click', () => switchTab(newButton));

            tabsContainer.appendChild(newButton);

            // 3. Update Editor and State
            document.getElementById('editor').value = initialContent;
        }

        /** Saves the current content of the active editor tab to localStorage */
        function saveCurrentTabData() {
             const editorEl = document.getElementById('editor');
             let currentTabsState = JSON.parse(localStorage.getItem(TABS_STORAGE_KEY) || '[]');

             // Find which tab is currently active (by checking the .active class)
             const tabsContainer = document.getElementById('tabs');
             const activeButton = tabsContainer.querySelector('.tab.active');

             if (activeButton) {
                 const activeId = activeButton.dataset.tabId;
                 // Update content for that specific ID
                 let tabFound = currentTabsState.find(t => t.id === activeId);
                 if (tabFound) {
                     tabFound.content = editorEl.value;
                 } else {
                     // Fallback safety check: if somehow the ID isn't in state, assume it's the newest one
                      currentTabsState[0].content = editorEl.value;
                 }
             }

            localStorage.setItem(TABS_STORAGE_KEY, JSON.stringify(currentTabsState));
        }


        // =============================
        // 4. INITIALIZATION & EVENT BINDING
        // =============================

        function init() {
            // Initialize Notepad persistence and tabs
            const initialTabs = loadNotebookState();
            if (initialTabs.length === 0) {
                renderTabs([{ id: 'welcome', title: 'Welcome Note', content: '' }]);
            } else {
                 renderTabs(initialTabs);
            }

            // Event Listener for Editor Input Change (Saves on blur/change)
